-- =====================================================================
-- NutriBalance — banco de dados completo (esquema + dados)
--
-- Este e o UNICO arquivo necessario para instalar o banco. Ele cria o
-- banco `nutribalance`, as quatro tabelas e ja carrega os 597 alimentos da
-- Tabela Brasileira de Composicao de Alimentos (TACO), 4a edicao.
--
-- Como importar:
--   phpMyAdmin (http://localhost/phpmyadmin) > aba Importar > escolher
--   este arquivo > Executar.
--
--   Ou pela linha de comando:
--     D:\Xampp\mysql\bin\mysql.exe -u root < nutribalance_completo.sql
--
-- Rodar de novo e seguro: as tabelas sao preservadas (contas de usuario
-- e medicoes nao se perdem) e a tabela `alimentos` e recarregada do zero.
--
-- Para regerar este arquivo a partir da planilha da TACO, veja README.md.
-- =====================================================================

CREATE DATABASE IF NOT EXISTS nutribalance
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE nutribalance;

SET NAMES utf8mb4;


-- ---------------------------------------------------------------------
-- Tabela `alimentos` — base nutricional (TACO, 4a edicao)
-- Todos os valores sao por 100 g de parte comestivel do alimento.
-- Alimentada pelos INSERT no fim deste arquivo.
-- ---------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS alimentos (
  id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
  numero_taco   INT UNSIGNED NULL,               -- numero do alimento na TACO
  categoria     VARCHAR(80)  NULL,               -- grupo (ex: "Cereais e derivados")
  descricao     VARCHAR(255) NOT NULL,           -- nome do alimento

  -- macronutrientes e energia (por 100 g)
  umidade       DECIMAL(8,3) NULL,               -- %
  energia_kcal  DECIMAL(8,2) NULL,               -- kcal
  energia_kj    DECIMAL(8,2) NULL,               -- kJ
  proteina      DECIMAL(8,3) NULL,               -- g
  lipideos      DECIMAL(8,3) NULL,               -- g (gordura)
  carboidrato   DECIMAL(8,3) NULL,               -- g
  fibra         DECIMAL(8,3) NULL,               -- g
  colesterol    DECIMAL(8,2) NULL,               -- mg
  cinzas        DECIMAL(8,3) NULL,               -- g

  -- minerais (por 100 g)
  calcio        DECIMAL(10,3) NULL,              -- mg
  magnesio      DECIMAL(10,3) NULL,              -- mg
  manganes      DECIMAL(10,3) NULL,              -- mg
  fosforo       DECIMAL(10,3) NULL,              -- mg
  ferro         DECIMAL(10,3) NULL,              -- mg
  sodio         DECIMAL(10,3) NULL,              -- mg
  potassio      DECIMAL(10,3) NULL,              -- mg
  cobre         DECIMAL(10,3) NULL,              -- mg
  zinco         DECIMAL(10,3) NULL,              -- mg

  -- vitaminas (por 100 g)
  retinol       DECIMAL(10,3) NULL,              -- mcg
  rae           DECIMAL(10,3) NULL,              -- mcg
  tiamina       DECIMAL(10,3) NULL,              -- mg
  riboflavina   DECIMAL(10,3) NULL,              -- mg
  piridoxina    DECIMAL(10,3) NULL,              -- mg
  niacina       DECIMAL(10,3) NULL,              -- mg
  vitamina_c    DECIMAL(10,3) NULL,              -- mg

  PRIMARY KEY (id),
  KEY idx_descricao (descricao),
  KEY idx_categoria (categoria),
  FULLTEXT KEY ft_descricao (descricao)          -- usada pela busca em api/buscar.php
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- Tabela `usuarios` — login + dados da personalizacao
-- Os campos de personalizacao ficam NULL ate o usuario concluir o
-- onboarding; `meta_kcal IS NOT NULL` significa perfil completo.
-- ---------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS usuarios (
  id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
  nome          VARCHAR(120) NOT NULL,
  email         VARCHAR(190) NOT NULL,
  senha_hash    VARCHAR(255) NOT NULL,             -- password_hash (PASSWORD_DEFAULT)
  foto          VARCHAR(255) NULL,                 -- caminho em site/uploads/fotos/ (NULL = usa as iniciais do nome)

  -- personalizacao (NULL ate o usuario completar o onboarding)
  sexo          ENUM('M','F') NULL,
  idade         INT UNSIGNED NULL,                 -- anos
  altura_cm     INT UNSIGNED NULL,                 -- cm
  peso_kg       DECIMAL(5,1)  NULL,                -- kg (peso atual)
  cintura_cm    DECIMAL(5,1)  NULL,                -- cm (cintura atual, opcional)
  peso_alvo     DECIMAL(5,1)  NULL,                -- kg (so quando meta = 'perder')
  atividade     ENUM('sedentario','leve','moderado','intenso','muito_intenso') NULL,
  meta          ENUM('perder','manter','ganhar') NULL,
  objetivo      ENUM('manter','definir') NULL,     -- so quando meta = 'manter' (definir = recomposicao)

  -- metas calculadas (meta_kcal IS NOT NULL == perfil completo)
  meta_kcal     INT UNSIGNED NULL,                 -- kcal/dia
  meta_carbo    INT UNSIGNED NULL,                 -- g
  meta_proteina INT UNSIGNED NULL,                 -- g
  meta_gordura  INT UNSIGNED NULL,                 -- g

  criado_em     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (id),
  UNIQUE KEY uq_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- Tabela `medicoes` — historico de peso e cintura ao longo do tempo
-- Um registro por dia por usuario. O peso ATUAL continua em
-- `usuarios.peso_kg`; aqui fica a evolucao que alimenta o grafico.
-- ---------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS medicoes (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  usuario_id  INT UNSIGNED NOT NULL,
  data        DATE          NOT NULL,          -- dia da medicao
  peso_kg     DECIMAL(5,1)  NOT NULL,          -- kg
  cintura_cm  DECIMAL(5,1)  NULL,              -- cm (opcional)
  criado_em   TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (id),
  UNIQUE KEY uq_usuario_data (usuario_id, data),   -- um registro por dia (permite o upsert)
  CONSTRAINT fk_medicoes_usuario
    FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- Tabela `redefinicoes_senha` — pedidos de "esqueci minha senha"
--
-- Guarda apenas o SHA-256 do token que foi enviado por e-mail, nunca o
-- token em si: se o banco vazar, os links ja emitidos continuam inuteis
-- (mesma logica de guardar `senha_hash` em vez da senha).
--
-- Um pedido so vale enquanto `usado_em IS NULL` e `expira_em > NOW()`,
-- ou seja: uso unico e com prazo de validade.
-- ---------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS redefinicoes_senha (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  usuario_id  INT UNSIGNED NOT NULL,
  token_hash  CHAR(64)     NOT NULL,          -- sha256 do token enviado no link
  expira_em   DATETIME     NOT NULL,          -- prazo de validade do link
  usado_em    DATETIME     NULL,              -- NULL = ainda nao foi usado
  criado_em   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (id),
  UNIQUE KEY uq_token_hash (token_hash),
  KEY idx_usuario_pendente (usuario_id, usado_em),
  CONSTRAINT fk_redefinicoes_usuario
    FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- Dados da tabela `alimentos` (TACO, 4a edicao — 597 alimentos)
-- O TRUNCATE deixa a reimportacao segura: recarrega os alimentos sem
-- duplicar, e sem tocar nas contas de usuario nem no historico.
-- ---------------------------------------------------------------------

TRUNCATE TABLE alimentos;


-- fim dos dados (597 alimentos da TACO 4a edicao)
